#include <Arduino.h>
#include <Servo.h>
Servo servo1;
Servo servo2;
Servo servo3;
const int LED_PINS[] = {5, 6, 7, 8, 9, 10, 11, 12, 13, 44};

void setup();
void loop();
void setup() {
  servo1.attach(2);  
  servo2.attach(3);  
  servo3.attach(4);  
  for (int i = 0; i < 10; i++) {
    pinMode(LED_PINS[i], OUTPUT);
    digitalWrite(LED_PINS[i], LOW);
  }
}
void loop() {
  servo1.write(180);
  servo2.write(0);
  servo3.write(0);
  for (int i = 0; i < 3; i++) digitalWrite(LED_PINS[i], HIGH);
  delay(2000);
  servo2.write(180);
  for (int i = 3; i < 6; i++) digitalWrite(LED_PINS[i], HIGH);
  delay(2000);
  servo3.write(180);
  for (int i = 6; i < 10; i++) digitalWrite(LED_PINS[i], HIGH);
  delay(2000);
  servo1.write(0);
  servo2.write(0);
  servo3.write(0);
  for (int i = 0; i < 10; i++) digitalWrite(LED_PINS[i], LOW);
  delay(2000);
}
